import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * Pack complete context sections into a deterministic UTF-8 byte budget.
 *
 * @param {unknown} sections
 * @param {unknown} maxBytes
 * @returns {{text:string, bytes:number, included:string[], omitted:string[]}}
 */
export function packContext(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    throw new Error('sections must be an array');
  }

  const ids = new Set();
  const validated = [];

  // Validate and frame every entry before making any packing decision.
  for (let index = 0; index < sections.length; index += 1) {
    if (!(index in sections)) {
      throw new Error(`sections must be dense (missing index ${index})`);
    }

    const section = sections[index];
    if (typeof section !== 'object' || section === null || Array.isArray(section)) {
      throw new Error(`section at index ${index} must be a non-null, non-array object`);
    }
    if (typeof section.id !== 'string' || section.id.length === 0) {
      throw new Error(`section at index ${index} has an invalid id`);
    }
    if (typeof section.text !== 'string') {
      throw new Error(`section at index ${index} has invalid text`);
    }
    if (!Number.isSafeInteger(section.priority) || section.priority < 0) {
      throw new Error(`section at index ${index} has an invalid priority`);
    }
    if (typeof section.required !== 'boolean') {
      throw new Error(`section at index ${index} has an invalid required flag`);
    }
    if (ids.has(section.id)) {
      throw new Error(`duplicate section id at index ${index}`);
    }
    ids.add(section.id);

    const frame = `### ${JSON.stringify(section.id)}\n${section.text}\n`;
    validated.push({
      id: section.id,
      priority: section.priority,
      required: section.required,
      index,
      frame,
      cost: Buffer.byteLength(frame, 'utf8'),
    });
  }

  const required = validated.filter((section) => section.required);
  const optional = validated
    .filter((section) => !section.required)
    .sort((left, right) => right.priority - left.priority || left.index - right.index);

  let bytes = 0;
  const frames = [];
  const included = [];
  const includedOptional = new Set();

  for (const section of required) {
    if (section.cost > maxBytes - bytes) {
      throw new Error('required sections exceed maxBytes');
    }
    bytes += section.cost;
    frames.push(section.frame);
    included.push(section.id);
  }

  for (const section of optional) {
    if (section.cost <= maxBytes - bytes) {
      bytes += section.cost;
      frames.push(section.frame);
      included.push(section.id);
      includedOptional.add(section.index);
    }
  }

  const omitted = validated
    .filter((section) => !section.required && !includedOptional.has(section.index))
    .map((section) => section.id);

  return { text: frames.join(''), bytes, included, omitted };
}

function runCli() {
  try {
    if (process.argv.length !== 3) {
      throw new Error('exactly one INPUT_JSON_FILE argument is required');
    }
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    const result = packContext(input.sections, input.maxBytes);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`context-packet: ${message}\n`);
    process.exitCode = 2;
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  runCli();
}

