import assert from 'node:assert/strict';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, resolve} from 'node:path';
import {spawnSync} from 'node:child_process';
import {packContext} from './context-packet.js';

const dir=mkdtempSync(join(tmpdir(),'context-packet-smoke-'));
try {
  const valid=join(dir,'valid.json');
  writeFileSync(valid,JSON.stringify({sections:[{id:'rule',text:'x',priority:0,required:true}],maxBytes:100}));
  let run=spawnSync(process.execPath,[resolve('context-packet.js'),valid],{encoding:'utf8'});
  assert.equal(run.status,0);
  assert.equal(run.stderr,'');
  assert.deepEqual(JSON.parse(run.stdout),packContext([{id:'rule',text:'x',priority:0,required:true}],100));
  assert.ok(run.stdout.endsWith('\n'));

  run=spawnSync(process.execPath,[resolve('context-packet.js')],{encoding:'utf8'});
  assert.equal(run.status,2);
  assert.equal(run.stdout,'');
  assert.notEqual(run.stderr,'');

  const bad=join(dir,'bad.json');
  writeFileSync(bad,'{');
  run=spawnSync(process.execPath,[resolve('context-packet.js'),bad],{encoding:'utf8'});
  assert.equal(run.status,2);
  assert.equal(run.stdout,'');
  assert.notEqual(run.stderr,'');

  assert.deepEqual(packContext([],Number.MAX_SAFE_INTEGER),{text:'',bytes:0,included:[],omitted:[]});
  assert.throws(()=>packContext([],Number.MAX_SAFE_INTEGER+1),Error);
  assert.throws(()=>packContext([{id:'x',text:'x',priority:Number.MAX_SAFE_INTEGER+1,required:false}],100),Error);
  console.log('CLI and numeric-boundary smoke checks passed');
} finally { rmSync(dir,{recursive:true,force:true}); }
EOF

